# -*- coding: utf-8 -*-
"""main-группа: node-isolate оркестратора (v0.4 — тулзы delegate / ask-user / answer-user / reject [AR-31], транскрипт [AR-28])."""
from common import test, CTX_M, cafe_ctx_many, STAND_K20
import main_fix as F

P = "main/node-isolate/orchestrator"

J_TASK = "- LLM-judge: `judge-orch-task` — запрос агенту (prompt тулзы `delegate`) полный: сервер, что узнать, период или момент, параметры из запроса пользователя; без команд; без выдуманных путей и фактов. Засчитан при всех критериях."
J_ARCH = "- LLM-judge: `judge-orch-arch` — только факты из документа контекста; ничего не выдумано; вопрос закрыт."
J_REPORT = "- LLM-judge: `judge-orch-report` — все числа и факты агента перенесены точно; причины не выдуманы; период или момент данных назван; источники названы понятным языком, имена ручек, команд и классов не названы [UC-22]."
J_READ = "- LLM-judge: `judge-readability` `[предл.]` (пункт плана MR-1d) — ответ читается без подготовки: не сырой вывод тулз (таблица на сотни строк, JSON, список записей), главное выделено и прокомментировано — что это значит и на что обратить внимание; длинные перечни свёрнуты в итоги с примерами; объём соразмерен вопросу."
J_Q = "- LLM-judge: `judge-orch-question` — (1) язык понятен пользователю: нет имён ручек, источников как идентификаторов, классов, тегов как идентификаторов (теги в скобках рядом с описанием, как в примере контракта [K §2.2], допустимы); (2) суть донесена верно. Засчитан при обоих."
REFUSAL = "- Доп. рубрика `judge-orch-refusal` `[предл.]` — вне долей v0.2 (текст отказа judge-метрикой не покрыт): нет инструкций и команд для изменений [UC-06]; нет имитации выполнения; имена ручек не названы [UC-22]; нет предложения «можно добавить в перечень» [UC-25]; причина отказа понятна."
NO_DELEG = "Агент в тесте не участвует — проверяется только оркестратор; транскрипт сессии пуст, счётчики тулз — 0."
REPORT_CLASS = "Класс итогового сообщения после ответа агента — `answered` (тулза `answer-user`; в M «ответ без делегации», по AR-31 класс = вызванная тулза — README, открытые пункты). Критерий «все числа агента перенесены точно» читается так `[предл.]`: обязательные числа из «Эталона» есть в ответе, любое другое число из ответа агента, если оно попало в ответ, совпадает."
TOOLS_NOTE = "Ответ оркестратора — вызов одной из четырёх тулз [AR-31]; rule-based класс = имя тулзы: `delegate` → `delegated`, `ask-user` → `clarify`, `answer-user` → `answered`, `reject` → `not_in_scope`."

CAPS_REF = """Эталонный перечень возможностей системы — фикстура вместо инструкций оркестратора (промпт не определён — `architecture/orchestrator-agent.md`), составлена по контракту [K §2.1] и решениям 2026-10-26/27:\n\n- ответы о состоянии и истории серверов по накопленным логам — нагрузка, место, службы, входы, задания, бэкапы, 1С и СУБД по тому, что стоит на сервере;\n- ответы о состоянии «прямо сейчас» — разовые проверки чтением;\n- ответы об архитектуре — где что стоит и какой сервер за что отвечает;\n- вопрос может затрагивать несколько серверов — система опросит их по очереди, не больше 15 за запрос [UC-26], [AR-32];\n- добавление сервера через форму и удаление сервера;\n- система только читает: ничего не меняет на серверах, не выполняет произвольные команды и скрипты, не даёт инструкций для изменений;\n- ничего не делает по расписанию, не присылает сводок и предупреждений, новые логи по просьбе не заводит;\n- секреты не хранит и не выдаёт."""


def transcript(*lines):
    return "Транскрипт сессии (оркестратор перезапущен с ним [AR-28]):\n\n" + "\n".join("- " + l for l in lines)


