def answered():
    test(P + "/answered/01-capabilities", "orchestrator/answered/01 — «что ты умеешь делать?»", [
        ("Сценарий", "Пункт плана MR-8a: что умеет вся система — общие возможности оркестратора. Пользователь спрашивает о возможностях; оркестратор отвечает сам (`answer-user`), ничего не делегируя. Наследник старого no-delegation/01."),
        ("Контекст оркестратора", CTX_M + "\n\n" + CAPS_REF),
        ("Вход", "Запрос пользователя: «что ты умеешь делать?». " + NO_DELEG),
        ("Ожидаемое поведение", """- Тулза `answer-user` (класс `answered`), делегирования нет.
- Названо, что умеет система: отвечать о состоянии и истории серверов по накопленным данным (нагрузка, место на дисках, службы, входы, задания планировщика, бэкапы, 1С и СУБД — по тому, что стоит на сервере); о состоянии «прямо сейчас»; об архитектуре — какой сервер за что отвечает; при необходимости опросить несколько серверов по очереди; добавлять серверы через форму и удалять их.
- Названы четыре сервера из контекста с ролями.
- Сказано, что система только читает: на серверах ничего не меняет, команд и скриптов не выполняет; по расписанию ничего не делает и сама не предупреждает.
- Ошибки: `reject`; обещание перезапусков, деплоя, изменений, ежедневных сводок, алертов или дашбордов; «перед каждым действием покажу карточку подтверждения»; выдуманные серверы; имена ручек."""),
        ("Эталон", "- Тулза: `answer-user` (`answered`); `delegate` не вызван."),
        ("Метрики", "- Rule-based: `orch-no-delegation` (`answered`, не `delegated`).\n" + J_ARCH.replace("только факты из документа контекста", "только факты из документа контекста и эталонного перечня возможностей")),
        ("Основания", "[UC-06], [UC-07], [UC-11], [UC-12], [UC-26], [K §2.1], [AR-31]. Не обсуждалось: запросы о самой системе («что ты умеешь») явно не разбирались (`user-contract/work-prompt.md`) — класс `answered` по аналогии с архитектурным вопросом `[предл.]`."),
        ("Данные", "Документ контекста стенда M, эталонный перечень возможностей, запрос, рубрика judge."),
    ], scenario="MR-8a")

    test(P + "/answered/02-architecture", "orchestrator/answered/02 — «расскажи мне про архитектуру»", [
        ("Сценарий", "Архитектурный вопрос [UC-12]: оркестратор пересказывает документ контекста — серверы, роли и связи, только то, что следует из кратких описаний и кратких описаний по тегам."),
        ("Контекст оркестратора", CTX_M),
        ("Вход", "Запрос пользователя: «расскажи мне про архитектуру». " + NO_DELEG),
        ("Ожидаемое поведение", """- `answer-user` (`answered`), делегирования нет.
- Четыре сервера с ролями: сайт на VPS у хостера; сервер 1С с Бухгалтерией и ЗУП на PostgreSQL; микросервисы бухгалтерии в Docker с распознаванием документов на GPU; шлюз с туннелями.
- Связи — из кратких описаний: сайт раз в час забирает прайс из 1С, 1С публикует данные для обмена с сайтом; склад работает в 1С через туннель шлюза; шлюз держит туннель до VPS сайта.
- Платформа хостера — допустимо сказать, что она не обслуживается, без имени тега.
- Ошибки: связь «микросервисы читают данные 1С» (её нет в описаниях); версии платформы и порты кластера (их нет в контексте — только в `tags-full-desc` у агента); пометка «1С — критичный» как факт из контекста; выдуманные серверы."""),
        ("Эталон", "- Тулза: `answer-user` (`answered`).\n- Факты: 4 сервера; связи сайт ↔ 1С (прайс раз в час), склад → 1С через туннель gw-01, gw-01 → VPS сайта."),
        ("Метрики", "- Rule-based: `orch-no-delegation`.\n" + J_ARCH),
        ("Основания", "[UC-04], [UC-12], [AR-22] — ответ из `server-name`, `conn-ip`, `tags`, `short-desc` (и `tags-short-desc` `[предл.]` [Q56]); [UC-16] — имя `unsupported:*` не называется."),
        ("Данные", "Документ контекста стенда M, запрос, эталонные факты, рубрика judge."),
    ])

    test(P + "/answered/03-server-info-1c", "orchestrator/answered/03 — «расскажи мне про сервер с 1С»", [
        ("Сценарий", "Рассказ о сервере из контекста оркестратора (пункт «Server info» скриншота плана): оркестратор отвечает кратким описанием и краткими описаниями по тегам, не обращаясь к агенту, и не придумывает подробностей, которых у него нет; изменчивые факты (кто сейчас в базе, сколько места) — не из памяти (пункт MR-7b — `delegated/13`)."),
        ("Контекст оркестратора", CTX_M),
        ("Вход", "Запрос пользователя: «расскажи мне про сервер с 1С». " + NO_DELEG),
        ("Ожидаемое поведение", """- `answer-user` (`answered`), делегирования нет.
- srv-1c, 10.0.1.12: 1С с базами Бухгалтерия и ЗУП на PostgreSQL, около 12 пользователей; публикует данные 1С для обмена с сайтом; ночной бэкап баз; по тегам — кластер 8.3.24, PostgreSQL 16, подрядчик «1С-Партнёр». Уместно: сайт забирает из 1С прайс раз в час; склад работает в 1С через туннель шлюза.
- Технических подробностей сверх контекста нет; допустимо предложить узнать текущее состояние у сервера (диски, нагрузка, сеансы).
- Ошибки: делегирование; порты кластера, пути, имена баз в СУБД (их нет в контексте); текущее число сеансов как факт."""),
        ("Эталон", "- Тулза: `answer-user` (`answered`) `[предл.]`; факты — `short-desc` и `tags-short-desc` srv-1c, связи из описаний web-01 и gw-01."),
        ("Метрики", "- Rule-based: `orch-no-delegation`.\n" + J_ARCH),
        ("Основания", "[UC-04], [UC-12], [K §2.2] «Архитектурный вопрос». Не обсуждалось: запрос «расскажи всё про srv-1c» при полном описании у агента (`user-contract/architecture-question.md`) — альтернатива `delegate`. Эталон `answered` `[предл.]`: в плане «Server info» стоит отдельно от «Fact check → now, not memo»."),
        ("Данные", "Документ контекста стенда M, запрос, рубрика judge."),
    ])

    test(P + "/answered/04-where-1c-and-dbms", "orchestrator/answered/04 — «где у нас стоит 1С и какая там СУБД?»", [
        ("Сценарий", "Пример архитектурного вопроса из контракта [K §2.2]. Ответ есть в контексте: тег db/pg и краткие описания srv-1c."),
        ("Контекст оркестратора", CTX_M),
        ("Вход", "Запрос пользователя: «где у нас стоит 1С и какая там СУБД?». " + NO_DELEG),
        ("Ожидаемое поведение", """- `answer-user` (`answered`), делегирования нет.
- 1С — на srv-1c (10.0.1.12); СУБД — PostgreSQL (16 — из краткого описания по тегу).
- Ошибки: делегирование агенту; MariaDB сайта как СУБД 1С; уточняющий вопрос."""),
        ("Эталон", "- Тулза: `answer-user` (`answered`); факты: srv-1c, 10.0.1.12, PostgreSQL."),
        ("Метрики", "- Rule-based: `orch-no-delegation`.\n" + J_ARCH),
        ("Основания", "[K §2.2], [UC-12]. Граница «из контекста или у агента» для вопросов о составе сервера — [предл.] правило README, открытые пункты (п. «факт из памяти или с сервера»)."),
        ("Данные", "Документ контекста стенда M, запрос, рубрика judge."),
    ])


